-- CLIENTES (50 registros)

-- CATEGORIAS (50 registros)

-- PRODUCTOS (50 registros)

-- PROVEEDORES (50 registros)

-- PRODUCTO_PROVEEDOR (50 registros)

-- BODEGAS (50 registros)

-- UBICACIONES (50 registros)

-- INVENTARIO (50 registros)

-- ORDENES_PEDIDO (50 registros)

-- DETALLE_ORDEN (50 registros)

-- TRANSPORTISTAS (50 registros)

-- EMPLEADOS (50 registros)

-- ENVIOS (50 registros)

-- COMPROBACION: cada tabla debe devolver 50
SELECT 'clientes' AS tabla, COUNT(*) AS cantidad FROM clientes UNION ALL
SELECT 'categorias', COUNT(*) FROM categorias UNION ALL
SELECT 'productos', COUNT(*) FROM productos UNION ALL
SELECT 'proveedores', COUNT(*) FROM proveedores UNION ALL
SELECT 'producto_proveedor', COUNT(*) FROM producto_proveedor UNION ALL
SELECT 'bodegas', COUNT(*) FROM bodegas UNION ALL
SELECT 'ubicaciones', COUNT(*) FROM ubicaciones UNION ALL
SELECT 'inventario', COUNT(*) FROM inventario UNION ALL
SELECT 'ordenes_pedido', COUNT(*) FROM ordenes_pedido UNION ALL
SELECT 'detalle_orden', COUNT(*) FROM detalle_orden UNION ALL
SELECT 'transportistas', COUNT(*) FROM transportistas UNION ALL
SELECT 'empleados', COUNT(*) FROM empleados UNION ALL
SELECT 'envios', COUNT(*) FROM envios
ORDER BY tabla;

COMMIT;
